function dropFromEnd(head: ListNode | null, k: number): ListNode | null {
  let len = 0;
  for (let n = head; n; n = n.next) len++;
  const dummy = new ListNode(0, head);
  let prev = dummy;
  for (let i = 0; i < len - k; i++) prev = prev.next!;
  prev.next = prev.next!.next;
  return dummy.next;
}

