class Solution:
    def dropFromEnd(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        length, n = 0, head
        while n:
            length += 1
            n = n.next
        dummy = prev = ListNode(0, head)
        for _ in range(length - k):
            prev = prev.next
        prev.next = prev.next.next
        return dummy.next

