function dropFromEnd(head: ListNode | null, k: number): ListNode | null {
  const dummy = new ListNode(0, head);
  let lead: ListNode = dummy, trail: ListNode = dummy;
  for (let i = 0; i < k; i++) lead = lead.next!;
  while (lead.next) {
    lead = lead.next;
    trail = trail.next!;
  }
  trail.next = trail.next!.next;
  return dummy.next;
}

